const o={ui:{fig:"Fig. 2",title:"Cut-out corners",svgLabel:"An isometric drawing of how cut-out corners are made: the piece folded in half and sewn at the sides, a 3.5 × 2.5 cm piece cut from each bottom corner, each corner opened with the side seam on the bottom fold and sewn straight across, and the bag turned out with a flat bottom.",prev:"Previous step",dot:(t,e)=>t?`Step ${t}: ${e}`:e,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(t,e)=>`Step ${t} of ${e}`,machine:t=>`Machine: ${t.toLowerCase()}`,inThisStep:"In this step",takeApart:"Stand it up",putTogether:"Show the bottom",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW"},stitches:{straight:"Straight stitch"},labels:{cm23:"23 cm",cm31:"31 cm",rightSides:"right sides together",foldBottom:"the fold is the bottom",seam05:"0.5 cm seam",cm35:"3.5 cm",cm25:"2.5 cm",cutBoth:"cut through both layers",seamOnFold:"side seam on the fold",sewAcross:"sew straight across",bothCorners:"both corners",turnOut:"turn it right side out",flatBottom:"a flat bottom",cornerSeam:"corner seam"},steps:[{title:"Cut-out corners",text:"The makeup bag's bottom, the bag upside down: a flat bottom with a short seam straight across each end, where the side seam meets the bottom fold. Tap the bag to stand it up."},{title:"Fold it in half",text:"The makeup bag is one 23 × 31 cm (9 × 12¼ in) piece. Fold it in half across its length, right sides together: the fold is the bottom.",details:["Lay the 23 × 31 cm (9 × 12¼ in) piece right side up.","Fold it in half across its length, right sides together. The fold is the bottom of the bag — there is no seam there.","The makeup bag's lining is the same 23 × 31 cm piece and is made the same way."]},{title:"Sew the sides",text:"Sew both sides with a 0.5 cm (³⁄₁₆ in) seam, from the top down to the fold.",details:["Clip the sides together.","Sew both side seams, 0.5 cm (³⁄₁₆ in) from the edge, all the way down to the fold.","On the makeup bag the zipper is sewn in first, and one side seam of the lining keeps an opening for turning; the corners are made the same way."]},{title:"Cut out the corners",text:"From each bottom corner cut a 3.5 × 2.5 cm (1⅜ × 1 in) piece: 3.5 cm along the bottom, 2.5 cm along the side seam.",details:["Mark a 3.5 × 2.5 cm (1⅜ × 1 in) rectangle in each bottom corner: 3.5 cm along the bottom fold, 2.5 cm up the side seam.","Cut it out through both layers.","On the makeup bag that is four corners: two on the outer, two on the lining."]},{title:"Open the corner",text:"Open each cut corner and flatten it so that the side seam lies on the bottom fold: the cut edges form one straight line.",details:["Open the cut corner, pulling the front and the back apart.","Flatten it so that the side seam lies right on the bottom fold.","The cut edges now form one straight line across the corner."]},{title:"Sew straight across",text:"Sew straight across each corner, 0.5 cm (³⁄₁₆ in) from the cut edge.",details:["Sew straight across the corner, 0.5 cm (³⁄₁₆ in) from the edge.","Do the other corner the same way — on the makeup bag, the two corners of the lining too."]},{title:"Turn it out",text:"Turn the bag right side out: it has a flat bottom, with a short corner seam across each end.",details:["Turn the bag right side out (the makeup bag turns through the opening in its lining) and push the corners out.","The bottom is flat. At each end the side seam meets the middle of the corner seam."]}],legend:[{title:"Bottom",text:"flat · between the two corner seams"},{title:"Bottom fold",text:"the 23 × 31 cm (9 × 12¼ in) piece folded in half · no seam on the bottom"},{title:"Corner seams",text:"sewn straight across, 0.5 cm (³⁄₁₆ in) from the edge, after a 3.5 × 2.5 cm (1⅜ × 1 in) piece was cut from the corner"},{title:"Side seams",text:"0.5 cm (³⁄₁₆ in) · each meets the middle of a corner seam"}]};export{o as default};
